def _enable_row_level_security() -> None:
    # The tenant for the current transaction, set by the API/worker with set_config('app.company_id', ..., true).
    # Unset or empty => NULL => no rows are visible or writable.
    op.execute(
        """
        CREATE FUNCTION app_current_company() RETURNS uuid LANGUAGE sql STABLE AS
        $$ SELECT NULLIF(current_setting('app.company_id', true), '')::uuid $$
        """
    )
    for table in TENANT_TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY tenant_isolation ON {table} "
            "USING (company_id = app_current_company()) WITH CHECK (company_id = app_current_company())"
        )
    op.execute("ALTER TABLE companies ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE companies FORCE ROW LEVEL SECURITY")
    op.execute(
        "CREATE POLICY tenant_isolation ON companies "
        "USING (id = app_current_company()) WITH CHECK (id = app_current_company())"
    )
    op.execute(f"GRANT USAGE ON SCHEMA public TO {APP_ROLE}")
    op.execute(f"GRANT EXECUTE ON FUNCTION app_current_company() TO {APP_ROLE}")
    for table in [*TENANT_TABLES, "companies"]:
        op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON {table} TO {APP_ROLE}")
    # Companies are created by the system role (registration); the audit log is append-only for the app.
    op.execute(f"REVOKE INSERT, DELETE ON companies FROM {APP_ROLE}")
    op.execute(f"REVOKE UPDATE, DELETE ON audit_logs FROM {APP_ROLE}")


